KG42.register("source_edge_archive-b55763f4b956e0447a078a1b",{"id":"15-multiagent_reverse_auction::v141-c-R009::E::v141-c-R009-E004","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R009","rule_ref":"15-multiagent_reverse_auction::v141-c-R009","record":{"edge_id":"v141-c-R009-E004","source":"participation.prosumer","target":"admission.local_area","type":"requires","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g01-E16"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R009-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-a1af16dd42f1ff08","target":"COMP-536dedc5bf0853eb","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R009::V::participation.prosumer","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R009::V::admission.local_area","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::participation.prosumer","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::admission.local_area","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Aggregator invitations to DER agents in the microgrid reverse auction. | Available generators seeking participation in the microgrid's hour-ahead reverse auction. | Continued DER participation during a rebidding round of the hourly microgrid auction. | DER bidding-agent decisions about joining the next hour's auction. | The initial DER participation test in Algorithm 1 for the microgrid reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E17"]},"active":true,"source_signature":"548b3e82c6e61dc03532fd210feadc9da94402e473c8bd73c1002ebc45f4e22e","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Participation by available microgrid generators requires yellow-pages registration, the stated admission requirement for this local market. Scope: Available generators seeking participation in the microgrid's hour-ahead reverse auction. Condition: The generator seeks to participate in bidding processes. The aggregator coordinates DER participation by inviting registered agents to participate in the auction. Scope: Aggregator invitations to DER agents in the microgrid reverse auction. Condition: The agents are registered to the yellow pages. Base-price information supplied by cost-function or state-of-charge agents informs the DER bidding agent's decision whether to participate. Scope: DER bidding-agent decisions about joining the next hour's auction. Condition: The DER is available for the next hour. Algorithm 1 conditions DER bidding participation on the comparison with the utility base-price signal: bidders submit when their base price is lower and otherwise drop without participating. Scope: The initial DER participation test in Algorithm 1 for the microgrid reverse auction. Condition: The DER base price is lower than the utility base price; the alternative branch specifies nonparticipation. A bidder that is no longer interested in the new submission drops out and quits the auction for that particular hour. Scope: Continued DER participation during a rebidding round of the hourly microgrid auction. Condition: Supply exceeds demand, prompting a lower-price bidding request, and the bidder is no longer interested in the new submission.","target_definition":"Available generators in the microgrid should register to the yellow pages in order to participate in bidding processes. Scope: Admission to the microgrid reverse auction's bidding processes. Condition: An available generator in the microgrid seeks to participate in bidding processes.","constraints":[{"constraint_id":"v141-c-R009-C001","kind":"logical","role":"core","statement":"Participation by available microgrid generators requires yellow-pages registration, the stated admission requirement for this local market. Scope: Available generators seeking participation in the microgrid's hour-ahead reverse auction. Condition: The generator seeks to participate in bidding processes.","expression":"forall available generator g in the microgrid: participate(g) => registered_yellow_pages(g)","formalization_origin":"source","template_id":null,"members":["participation.prosumer","admission.local_area"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E16","v141-b-g02-e001"]}],"evidence":[{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"A reverse auction model has been implemented and realistically operated. Algorithm 1 briefly expresses the simplified pseudo code of the proposed reverse auction model. In Algorithm 1, the process is continuous unless the program is terminated. All available generators in the microgrid should register to the yellow pages in order to participate in bidding processes. The required amount of load is assumed to be correctly estimated for each upcoming hour; therefore the aggregator agent has this information ready to inform all agents registered to the yellow page. The main purpose of the aggregator agent is to purchase the required amount of energy with the least cost. The aggregator agent collects the submitted bids and checks whether the submitted supply matches the demand."},{"evidence_id":"v141-b-g02-e001","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"All available generators in the microgrid should register to the yellow pages in order to participate in bidding processes."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Aggregator invitations to DER agents in the microgrid reverse auction. | Available generators seeking participation in the microgrid's hour-ahead reverse auction. | Continued DER participation during a rebidding round of the hourly microgrid auction. | DER bidding-agent decisions about joining the next hour's auction. | The initial DER participation test in Algorithm 1 for the microgrid reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E17"]},"source_record":{"edge_id":"v141-c-R009-E004","source":"participation.prosumer","target":"admission.local_area","type":"requires","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g01-E16"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}});
